export function getMPFCosts(itemName: string) {
  const cleanName = itemName.trim();
  const crateName = cleanName.endsWith('(Crate)') ? cleanName : `${cleanName} (Crate)`;
  return MPF_ITEMS_DATA[crateName] || MPF_ITEMS_DATA[cleanName] || {
    displayName: itemName,
    crateItemName: crateName,
    mpfCategory: 'Default',
    costs: { bmats: 100, rmats: 0, emats: 0, hemats: 0 },
    crateQty: 20
  };
}
